static int ref_eq(ZnRef a,ZnRef b) {
    return a.slot==b.slot && a.tensor==b.tensor && a.generation==b.generation;
}
static int same_event(const ZnEvent *a,const ZnEvent *b) {
    unsigned i;
    if(a->event!=b->event || a->tile_first!=b->tile_first || a->tile_count!=b->tile_count ||
       a->compute_node!=b->compute_node || a->operation!=b->operation ||
       a->read_count!=b->read_count || a->retire_count!=b->retire_count ||
       a->has_destination!=b->has_destination) return 0;
    if(a->has_destination && (a->destination.address!=b->destination.address ||
       a->destination.bytes!=b->destination.bytes || a->destination.channels!=b->destination.channels ||
       a->destination.height!=b->destination.height || a->destination.width!=b->destination.width ||
       !ref_eq(a->destination.ref,b->destination.ref))) return 0;
    for(i=0;i<a->read_count;i++) if(!ref_eq(a->reads[i],b->reads[i])) return 0;
    for(i=0;i<a->retire_count;i++) if(!ref_eq(a->retired[i],b->retired[i])) return 0;
    return 1;
}
